function criarFormulario(){return'\n\n        <section>\n\n            <h1>Faça parte da nossa comunidade</h1>\n\n            <p>\n                Cadastre-se para apoiar nossos projetos como doador,\n                voluntário ou ambos.\n            </p>\n\n            <div\n                id="form-alert"\n                class="alert alert-info"\n                role="alert"\n                aria-live="polite"\n            >\n                <strong>Informação:</strong>\n                Preencha seus dados para participar das nossas ações.\n            </div>\n\n        </section>\n\n\n        <section>\n\n            <h2>Formulário de cadastro</h2>\n\n            <form id="cadastro-form" novalidate>\n\n                <fieldset>\n\n                    <legend>Dados pessoais</legend>\n\n                    <label for="nome">\n                        Nome completo:\n                    </label>\n\n                    <input\n                        type="text"\n                        id="nome"\n                        name="nome"\n                        autocomplete="name"\n                        required\n                        aria-describedby="nome-error"\n                    >\n\n                    <span\n                        class="field-error"\n                        id="nome-error"\n                        role="alert"\n                    ></span>\n\n\n                    <label for="email">\n                        E-mail:\n                    </label>\n\n                    <input\n                        type="email"\n                        id="email"\n                        name="email"\n                        autocomplete="email"\n                        required\n                        aria-describedby="email-error"\n                    >\n\n                    <span\n                        class="field-error"\n                        id="email-error"\n                        role="alert"\n                    ></span>\n\n\n                    <label for="telefone">\n                        Telefone:\n                    </label>\n\n                    <input\n                        type="tel"\n                        id="telefone"\n                        name="telefone"\n                        autocomplete="tel"\n                        required\n                        aria-describedby="telefone-error"\n                    >\n\n                    <span\n                        class="field-error"\n                        id="telefone-error"\n                        role="alert"\n                    ></span>\n\n                </fieldset>\n\n\n                <fieldset>\n\n                    <legend>Como deseja contribuir?</legend>\n\n                    <label for="participacao">\n                        Tipo de participação:\n                    </label>\n\n                    <select\n                        id="participacao"\n                        name="participacao"\n                        required\n                        aria-describedby="participacao-error"\n                    >\n\n                        <option value="">\n                            Selecione uma opção\n                        </option>\n\n                        <option value="doador">\n                            Doador\n                        </option>\n\n                        <option value="voluntario">\n                            Voluntário\n                        </option>\n\n                        <option value="ambos">\n                            Doador e voluntário\n                        </option>\n\n                    </select>\n\n                    <span\n                        class="field-error"\n                        id="participacao-error"\n                        role="alert"\n                    ></span>\n\n\n                    <label for="mensagem">\n                        Como gostaria de contribuir?\n                    </label>\n\n                    <textarea\n                        id="mensagem"\n                        name="mensagem"\n                        rows="5"\n                        placeholder="Conte um pouco sobre como gostaria de participar."\n                    ></textarea>\n\n                </fieldset>\n\n\n                <button type="submit">\n                    Enviar cadastro\n                </button>\n\n            </form>\n\n        </section>\n\n    '}function configurarFormulario(){const e=document.querySelector("#cadastro-form");e&&e.addEventListener("submit",function(n){n.preventDefault(),limparErros();const o=document.querySelector("#nome"),r=document.querySelector("#email"),a=document.querySelector("#telefone"),t=document.querySelector("#participacao");let i=!0;if(""===o.value.trim()&&(mostrarErro("nome","Informe seu nome."),i=!1),""===r.value.trim()?(mostrarErro("email","Informe seu e-mail."),i=!1):r.validity.valid||(mostrarErro("email","Informe um e-mail válido."),i=!1),""===a.value.trim()&&(mostrarErro("telefone","Informe seu telefone."),i=!1),""===t.value&&(mostrarErro("participacao","Selecione uma forma de participação."),i=!1),!i)return void mostrarAlerta("Atenção: preencha corretamente os campos obrigatórios.","warning");const l={nome:o.value.trim(),email:r.value.trim(),telefone:a.value.trim(),participacao:t.value,mensagem:document.querySelector("#mensagem").value.trim()};salvarCadastro(l),mostrarAlerta("Cadastro realizado com sucesso e salvo no navegador!","success"),e.reset()})}function mostrarErro(e,n){const o=document.querySelector(`#${e}-error`);o&&(o.textContent=n)}function limparErros(){document.querySelectorAll(".field-error").forEach(function(e){e.textContent=""})}function mostrarAlerta(e,n){const o=document.querySelector("#form-alert");o&&(o.className=`alert alert-${n}`,o.innerHTML=`<strong>${e}</strong>`,o.scrollIntoView({behavior:"smooth",block:"center"}))}